const path='assets/routes/',identity=new THREE.Quaternion(),scaleOne=new THREE.Vector3(1,1,1);
const standard=(color,extra={})=>new THREE.MeshStandardMaterial({color,roughness:.7,...extra});
const glow=color=>new THREE.MeshBasicMaterial({color,toneMapped:false});
function flipGrid(geometry){const index=geometry.index;for(let i=0;i<index.count;i+=3){const a=index.getX(i+1);index.setX(i+1,index.getX(i+2));index.setX(i+2,a);}index.needsUpdate=true;}
function triplanar(material){const frame={value:new THREE.Vector4()};material.onBeforeCompile=shader=>{shader.uniforms.routeFrame=frame;shader.vertexShader=shader.vertexShader.replace('#include <common>','#include <common>\nuniform vec4 routeFrame; varying vec3 vRoutePosition; varying vec3 vRouteNormal;').replace('#include <begin_vertex>','#include <begin_vertex>\nvRoutePosition=vec3(position.x+routeFrame.z+routeFrame.w*(-position.z),position.y+routeFrame.y,routeFrame.x-position.z);vRouteNormal=normal;');shader.fragmentShader=shader.fragmentShader.replace('#include <common>','#include <common>\nvarying vec3 vRoutePosition; varying vec3 vRouteNormal;\nvec3 routeWeights(){vec3 w=pow(abs(normalize(vRouteNormal)),vec3(5.0));return w/max(dot(w,vec3(1.0)),0.0001);}\nvec4 routeSample(sampler2D tex){vec3 p=vRoutePosition/6.0,w=routeWeights();return texture2D(tex,p.yz)*w.x+texture2D(tex,p.xz)*w.y+texture2D(tex,p.xy)*w.z;}').replace('#include <map_fragment>','diffuseColor *= routeSample(map);').replace('#include <roughnessmap_fragment>','float roughnessFactor = roughness;\n#ifdef USE_ROUGHNESSMAP\nroughnessFactor *= routeSample(roughnessMap).g;\n#endif').replace('#include <normal_fragment_maps>','\n#ifdef USE_NORMALMAP\nvec3 rp=vRoutePosition/6.0,rw=routeWeights(),rn=normalize(vRouteNormal);\nvec3 nx=texture2D(normalMap,rp.yz).xyz*2.0-1.0,ny=texture2D(normalMap,rp.xz).xyz*2.0-1.0,nz=texture2D(normalMap,rp.xy).xyz*2.0-1.0;\nvec3 detail=normalize(vec3(nx.z*sign(rn.x),nx.y,nx.x)*rw.x+vec3(ny.x,ny.z*sign(rn.y),ny.y)*rw.y+vec3(nz.x,nz.y,nz.z*sign(rn.z))*rw.z);\nnormal=normalize(mix(normal,mat3(viewMatrix)*detail,0.35));\n#endif');};material.customProgramCacheKey=()=> 'route-triplanar-v1';return frame;}
function box(root,w,h,d,material,x=0,y=0,z=0,ry=0){const m=new THREE.Mesh(new THREE.BoxGeometry(w,h,d),material);m.position.set(x,y,z);m.rotation.y=ry;root.add(m);return m;}
function mergeRoot(root){root.updateMatrixWorld(true);const groups=new Map();root.traverse(m=>{if(!m.isMesh)return;const g=m.geometry.clone().applyMatrix4(m.matrixWorld);for(const name of Object.keys(g.attributes))if(!['position','normal','uv'].includes(name))g.deleteAttribute(name);if(!g.attributes.normal)g.computeVertexNormals();if(!g.attributes.uv)g.setAttribute('uv',new THREE.BufferAttribute(new Float32Array(g.attributes.position.count*2),2));const geo=g.index?g.toNonIndexed():g;if(g!==geo)g.dispose();if(!groups.has(m.material))groups.set(m.material,[]);groups.get(m.material).push(geo);});const result=new THREE.Group();for(const [material,parts] of groups){const g=mergeGeometries(parts,false);parts.forEach(p=>p.dispose());const mesh=new THREE.Mesh(g,material);mesh.castShadow=mesh.receiveShadow=true;result.add(mesh);}return result;}
function normalize(source,size,axis='y'){const g=source.clone(true),bounds=new THREE.Box3().setFromObject(g),extent=bounds.getSize(new THREE.Vector3()),center=bounds.getCenter(new THREE.Vector3());g.position.sub(new THREE.Vector3(center.x,bounds.min.y,center.z));const wrapper=new THREE.Group();wrapper.add(g);wrapper.scale.setScalar(size/extent[axis]);return mergeRoot(wrapper);}
function instancePool(proto,items,root,shadow=true){const meshes=proto.children.map(m=>{const inst=new THREE.InstancedMesh(m.geometry,m.material,items.length);inst.instanceMatrix.setUsage(THREE.DynamicDrawUsage);inst.castShadow=shadow;inst.receiveShadow=true;inst.frustumCulled=false;root.add(inst);return inst;});const transform=new THREE.Object3D();return {items,update(place){let visible=0;items.forEach((item,i)=>{place(item,transform,i);if(transform.scale.x<=0)return;transform.updateMatrix();for(const mesh of meshes)mesh.setMatrixAt(visible,transform.matrix);visible++;});for(const mesh of meshes){mesh.count=visible;mesh.instanceMatrix.needsUpdate=true;}}};}
const textureCache=new Map();
export function routeTextures(id,renderer){if(!textureCache.has(id))textureCache.set(id,fetchTextures(id,renderer).catch(e=>{textureCache.delete(id);throw e;}));return textureCache.get(id);}
const textures=routeTextures;
async function fetchTextures(id,renderer){const loader=new THREE.TextureLoader(),files=await Promise.all(['diff','nor_gl','rough'].map(k=>loader.loadAsync(path+id+'/'+id+'_'+k+'_2k.jpg')));files[0].colorSpace=THREE.SRGBColorSpace;for(const t of files){t.wrapS=t.wrapT=THREE.RepeatWrapping;t.anisotropy=Math.min(12,renderer.capabilities.getMaxAnisotropy());}return {map:files[0],normalMap:files[1],roughnessMap:files[2],normalScale:new THREE.Vector2(.8,.8)};}
function lampPrototype(){const root=new THREE.Group(),metal=standard('#29384a',{metalness:.7,roughness:.32}),light=glow('#b8eeff');box(root,.16,8,.16,metal,0,4);box(root,2.3,.12,.2,metal,-1.05,7.95);box(root,1.2,.07,.35,light,-1.6,7.84);box(root,.4,.4,.4,metal,0,.2);return mergeRoot(root);}
function lampPool(root,span=560){const pool=[],proto=lampPrototype();for(let i=0;i<20;i++){const g=proto.clone();g.userData={anchor:12+Math.floor(i/2)*56,x:i%2?7.3:-7.3,span};root.add(g);pool.push(g);}return pool;}
function windowMaps(){const c=document.createElement('canvas');c.width=512;c.height=1024;const e=document.createElement('canvas');e.width=c.width;e.height=c.height;const ctx=c.getContext('2d'),em=e.getContext('2d');ctx.fillStyle='#172533';ctx.fillRect(0,0,512,1024);em.fillStyle='#000000';em.fillRect(0,0,512,1024);for(let y=0;y<24;y++)for(let x=0;x<8;x++){const lit=(x*17+y*13)%9>4,px=x*64+6,py=y*42+5;ctx.fillStyle=lit?'#8099ac':'#284354';ctx.fillRect(px,py,51,30);ctx.fillStyle='#96afbf';ctx.fillRect(px,py,2,30);if(lit){em.fillStyle=(x+y)%3===0?'#e4c18e':'#7596af';em.fillRect(px+2,py+2,46,26);}}const map=new THREE.CanvasTexture(c),emissiveMap=new THREE.CanvasTexture(e);map.colorSpace=emissiveMap.colorSpace=THREE.SRGBColorSpace;return {map,emissiveMap};}
function tower(index,concrete,glass,trim,neon){const root=new THREE.Group(),w=10+index%3*3,d=10+index%2*4,h=28+index*9;box(root,w,h,d,glass,0,h/2);for(let f=0;f<=Math.round(h/3.4);f++)box(root,w+.3,.13,d+.3,trim,0,f*3.4);for(const x of [-w/2,w/2])box(root,.25,h,d+.4,concrete,x,h/2);box(root,w+1,.5,d+1,concrete,0,h);box(root,w*.45,3,d*.45,concrete,0,h+1.5);for(let j=0;j<3;j++){box(root,1.3,1.1,1.7,trim,-w*.3+j*2,h+.9,d*.2);box(root,.12,1.9,.12,trim,w*.27,h+1.9,-d*.2);}if(index%2===0)box(root,.15,h,.16,neon,-w/2-.22,h/2,d/2+.2);return mergeRoot(root);}
function banner(word,color){const c=document.createElement('canvas');c.width=1024;c.height=256;const ctx=c.getContext('2d');ctx.fillStyle='#0a1427';ctx.fillRect(0,0,1024,256);ctx.strokeStyle=color;ctx.lineWidth=9;ctx.strokeRect(12,12,1000,232);ctx.fillStyle=color;ctx.shadowColor=color;ctx.shadowBlur=14;ctx.font='bold 98px sans-serif';ctx.textAlign='center';ctx.fillText(word,512,162);const map=new THREE.CanvasTexture(c);map.colorSpace=THREE.SRGBColorSpace;return new THREE.MeshBasicMaterial({map,side:THREE.DoubleSide,toneMapped:false});}
function facadePrototype(kit,concrete){const wall=kit.getObjectByName('wall_window_centered_large_01'),window=kit.getObjectByName('window_centered_large_01');if(!wall||!window)throw Error('City facade modules missing');const root=new THREE.Group();box(root,11.8,18,11.8,concrete,0,9);for(let face=0;face<4;face++){const side=new THREE.Group(),angle=face*Math.PI/2;side.rotation.y=angle;side.position.set(Math.sin(angle)*6,0,Math.cos(angle)*6);for(let f=0;f<6;f++)for(let j=0;j<4;j++){for(const source of [wall,window]){const part=source.clone(true);part.position.set(j*3-3,f*3,0);side.add(part);}}root.add(side);}box(root,12.5,.35,12.5,concrete,0,18.15);for(const x of [-3,2])box(root,2,1.3,2.7,concrete,x,19.1,1);return mergeRoot(root);}
function cityScene(root,{concrete,kit}){let cuts=false,cutLength=3000;
 const frame=standard('#45566a',{metalness:.6,roughness:.3}),concreteDark=concrete.clone();concreteDark.color.set('#64717d');const cyan=glow('#78e4ff'),pink=glow('#f06ed4'),maps=windowMaps(),glass=standard('#a1bacc',{...maps,emissive:'#7ca6dc',emissiveIntensity:1.5,metalness:.65,roughness:.22});
 const towerPools=[];for(let kind=0;kind<6;kind++){const proto=tower(kind,concreteDark,glass,frame,kind%2?pink:cyan),items=Array.from({length:8},(_,i)=>({anchor:kind*40+Math.floor(i/2)*182,x:(i%2?1:-1)*(22+kind%3*15),angle:i%2?-.08:.06}));towerPools.push(instancePool(proto,items,root));}
 const apartments=instancePool(facadePrototype(kit,concrete),Array.from({length:10},(_,i)=>({anchor:70+Math.floor(i/2)*147,x:(i%2?1:-1)*14.6,angle:i%2?-Math.PI/2:Math.PI/2})),root);
 const lamps=lampPool(root),signs=[];for(let i=0;i<10;i++){const g=new THREE.Group(),m=new THREE.Mesh(new THREE.PlaneGeometry(6.8,1.7),banner(['NOVA / 07','HYPERION','SKYWAY ↗','ELECTRIC'][i%4],i%2?'#ff93df':'#7df2ff'));m.position.set(0,5.5,0);g.add(m);box(g,.2,5.5,.2,frame,0,2.75);g.userData={anchor:45+i*74,x:i%2?10.2:-10.2};root.add(g);signs.push(g);}
 const grounds=[];for(const side of [-1,1]){const geo=new THREE.PlaneGeometry(450,1000,1,100);geo.rotateX(-Math.PI/2);if(side>0)flipGrid(geo);const mesh=new THREE.Mesh(geo,concreteDark);mesh.receiveShadow=true;mesh.frustumCulled=false;root.add(mesh);grounds.push({mesh,side});}
 const pavement=[];for(const side of [-1,1]){const geo=new THREE.PlaneGeometry(10,520,1,104);geo.rotateX(-Math.PI/2);flipGrid(geo);const mesh=new THREE.Mesh(geo,concrete);mesh.receiveShadow=true;mesh.frustumCulled=false;root.add(mesh);pavement.push({mesh,side});}
 const bridgeParts=[];for(let i=0;i<52;i++){const g=new THREE.Group();box(g,13.2,.8,8.2,concrete,0,-.52);for(const x of [-6.4,6.4]){box(g,.36,.65,8.2,concreteDark,x,-.02);box(g,.07,.06,8.1,x<0?cyan:pink,x,.33);}const posts=[];for(const x of [-5.2,5.2])posts.push(box(g,.65,1,1.5,concreteDark,x,-1));g.userData={posts};root.add(g);bridgeParts.push(g);}
 const underpass=[];for(let i=0;i<26;i++){const g=new THREE.Group();box(g,21,1.1,8.3,concrete,0,6.8);for(const x of [-8.1,8.1]){box(g,.9,6.3,1.1,concreteDark,x,3.15);box(g,.1,.12,7.8,cyan,x,4.9);}box(g,1.6,.06,5.4,glow('#ffebce'),0,6.21);g.userData={anchor:CITY_UNDERPASS.start+i*8};root.add(g);underpass.push(g);}
 const cross=[];for(const anchor of [CITY_UNDERPASS.start+12,CITY_UNDERPASS.end-12]){const g=new THREE.Group();box(g,120,.6,16,concreteDark,0,8);box(g,120,.08,14,standard('#35424b',{roughness:.78}),0,8.35);for(const x of [-40,-20,0,20,40])box(g,8,.03,.15,glow('#c8d1cf'),x,8.41);for(const z of [-7.5,7.5])box(g,120,.9,.3,concrete,0,8.8,z);g.userData={anchor};root.add(g);cross.push(g);}
 const place=(item,o,d,track)=>{const f=sceneryForward(item.anchor,d,728,80);o.position.set(item.x+bend(f,d,track),-height(d,track),-f);o.rotation.set(0,-heading(f,d,track)+(item.angle||0),0);o.scale.setScalar(f<360&&!(cuts&&shortcutClearance(track,item.x,d+f,10,cutLength))?1:0);};
 return {lamps,update(s){cuts=s.gameMode==='race';cutLength=s.raceLength||3000;const d=s.distance,track=s.trackProfile;for(const pool of towerPools)pool.update((item,o)=>place(item,o,d,track));apartments.update((item,o)=>place(item,o,d,track));for(const {mesh,side} of grounds){const p=mesh.geometry.attributes.position,uv=mesh.geometry.attributes.uv;for(let i=0;i<p.count;i++){const f=-80+(i>>1)*10,x=side*(16+(i%2)*450);p.setXYZ(i,x+bend(f,d,track),-height(d,track)-.24,-f);uv.setXY(i,x/8,(d+f)/8);}p.needsUpdate=uv.needsUpdate=true;mesh.geometry.computeVertexNormals();}for(const {mesh,side} of pavement){const p=mesh.geometry.attributes.position,uv=mesh.geometry.attributes.uv;for(let i=0;i<p.count;i++){const f=-60+(i>>1)*5;const x=side*11+(i%2?5:-5);p.setXYZ(i,x+bend(f,d,track),-height(d,track)+(cuts&&shortcutClearance(track,x,d+f,10,cutLength)?-.2:.12),-f);uv.setXY(i,x/4,(d+f)/4);}p.needsUpdate=uv.needsUpdate=true;mesh.geometry.computeVertexNormals();}
  for(const g of lamps){const f=sceneryForward(g.userData.anchor,d,560,60);g.position.set(g.userData.x+bend(f,d,track),rise(f,d,track),-f);g.rotation.y=-heading(f,d,track)+(g.userData.x<0?Math.PI:0);g.visible=f<350&&!(cuts&&shortcutClearance(track,g.userData.x,d+f,5,cutLength));}
  for(const g of signs){const f=sceneryForward(g.userData.anchor,d,740,60);g.position.set(g.userData.x+bend(f,d,track),-height(d,track),-f);g.rotation.y=-heading(f,d,track)+(g.userData.x<0?.25:-.25);g.visible=f<350&&!(cuts&&shortcutClearance(track,g.userData.x,d+f,5,cutLength));}
  bridgeParts.forEach((g,i)=>{const f=Math.floor(d/8)*8-d-48+i*8,h=cityElevation(d+f);g.visible=h>.35;if(!g.visible)return;g.position.set(bend(f,d,track),rise(f,d,track),-f);g.rotation.y=-heading(f,d,track);g.rotation.x=Math.atan(grade(d+f,track));for(const post of g.userData.posts){post.scale.y=Math.max(.1,h-.9);post.position.y=-h*.5-.4;}});
  for(const g of [...underpass,...cross]){const f=((g.userData.anchor-d+80)%3000+3000)%3000-80;g.visible=f<370;if(g.visible){g.position.set(bend(f,d,track),-height(d,track),-f);g.rotation.y=-heading(f,d,track);}}
 }};
}
function mountainScene(root,{rock,cliff,boulder,details}){let cuts=false,cutLength=3000;
 const terrainMaterial=standard('#ffffff',{...rock,vertexColors:true,roughness:.92}),terrainFrame=triplanar(terrainMaterial),terrain=[];
 for(const side of [-1,1]){const geo=new THREE.PlaneGeometry(180,580,36,116);geo.rotateX(-Math.PI/2);if(side>0)flipGrid(geo);geo.setAttribute('color',new THREE.BufferAttribute(new Float32Array(geo.attributes.position.count*3),3));const mesh=new THREE.Mesh(geo,terrainMaterial);mesh.receiveShadow=true;mesh.frustumCulled=false;root.add(mesh);terrain.push({mesh,side});}
 const ridge=[];for(let layer=0;layer<3;layer++){const geo=new THREE.PlaneGeometry(1600,850,96,40);geo.rotateX(-Math.PI/2);const pos=geo.attributes.position;for(let i=0;i<pos.count;i++){const x=pos.getX(i),z=pos.getZ(i),height=48+layer*42+Math.pow(Math.abs(Math.sin(x*.006+z*.003+layer*3)),4)*100+Math.abs(Math.sin(x*.018+z*.011))*25;pos.setY(i,height);}geo.computeVertexNormals();const mat=standard(['#71828a','#a1afb2','#c7d0d2'][layer],{...rock,roughness:1});mat.map=mat.map.clone();mat.map.repeat.set(20,14);const mesh=new THREE.Mesh(geo,mat);mesh.position.set(layer%2?-120:160,-40-layer*12,-540-layer*210);root.add(mesh);ridge.push(mesh);}
 const cliffs=instancePool(normalize(cliff,12),Array.from({length:12},(_,i)=>({anchor:20+i*34,x:-15-(i%3)*1.2,angle:Math.PI/2,scale:.85+(i%4)*.12})),root);
 const boulders=instancePool(normalize(boulder,3.8),Array.from({length:6},(_,i)=>({anchor:60+i*73,x:i%2?13.3:-9.3,angle:i*1.7,scale:.75+(i%3)*.2})),root);
 const pine=details.texturedPine.clone(true);pine.traverse(o=>{if(o.isMesh){o.material=o.material.clone();if(o.material.name==='Textured foliage')o.material.color.set('#769874');}});const treeRoot=normalize(pine,7.5),trees=instancePool(treeRoot,Array.from({length:70},(_,i)=>({anchor:Math.floor(i/2)*15,x:(i%2?1:-1)*(11+(i*7%27)),angle:i*2.4,scale:.65+(i%5)*.18})),root);
 const lamps=lampPool(root,560);lamps.forEach((g,i)=>{g.userData.x=7.4;g.userData.anchor=i*28+14;g.scale.setScalar(.78);});
 const chevrons=[];for(let i=0;i<14;i++){const g=new THREE.Group(),metal=standard('#65717a',{metalness:.6});box(g,.08,2.1,.08,metal,0,1);const panel=new THREE.Mesh(new THREE.PlaneGeometry(1.35,.75),banner(i%2?'‹‹':'››','#ffe08c'));panel.position.y=2.1;g.add(panel);g.userData={anchor:75+i*39,x:i%2?7:-7};root.add(g);chevrons.push(g);}
 function groundOffset(x,global){const a=Math.abs(x)-6.2,edge=Math.min(1,Math.max(0,a/4));if(x<0)return edge*(2.5+a*.58+(Math.sin(global/37)+Math.sin(global/83+1))*2);return edge*(-Math.min(22,a*.85)+Math.max(0,a-45)*.8+(Math.sin(global/65)*3));}
 const color=new THREE.Color();
 function place(item,o,d,track,kind){const f=sceneryForward(item.anchor,d,kind==='tree'?540:440,60),y=rise(f,d,track)+groundOffset(item.x,d+f)-(kind==='cliff'?3:0);o.position.set(item.x+bend(f,d,track),y,-f);o.rotation.set(0,(item.angle||0)-heading(f,d,track),0);o.scale.setScalar(f<355&&!(cuts&&shortcutClearance(track,item.x,d+f,kind==='cliff'?11:6,cutLength))?(item.scale||1):0);}
 return {lamps,update(s){cuts=s.gameMode==='race';cutLength=s.raceLength||3000;const d=s.distance,track=s.trackProfile;terrainFrame.value.set(d,height(d,track),center(d,track),slope(d,track));for(const {mesh,side} of terrain){const p=mesh.geometry.attributes.position,uv=mesh.geometry.attributes.uv,colors=mesh.geometry.attributes.color;for(let i=0;i<p.count;i++){const row=Math.floor(i/37),col=i%37,f=-60+row*5,x=side*(6.2+col*5),offset=groundOffset(x,d+f),noise=Math.sin(x*.23+(d+f)*.047)*Math.sin(x*.11-(d+f)*.02)*Math.min(7,col*.7);p.setXYZ(i,x+bend(f,d,track),rise(f,d,track)+(cuts&&shortcutClearance(track,x,d+f,7,cutLength)?-.24:offset+noise-.12),-f);uv.setXY(i,(x+offset*.5)/12,(d+f)/12);const snow=s.worldId==='snow',vegetation=x>18&&x<95;if(snow)color.set('#e4edf0');else color.set(vegetation?'#82956c':x<-45?'#cbd1cd':'#b6b4a3');colors.setXYZ(i,color.r,color.g,color.b);}p.needsUpdate=uv.needsUpdate=colors.needsUpdate=true;mesh.geometry.computeVertexNormals();}
  ridge.forEach((m,i)=>{m.position.x=(i%2?-120:160)+Math.sin(d*.0004)*30;m.position.y=-height(d,track)-35-i*12;});cliffs.update((item,o)=>place(item,o,d,track,'cliff'));boulders.update((item,o)=>place(item,o,d,track,'rock'));trees.update((item,o)=>place(item,o,d,track,'tree'));
  for(const g of lamps){const f=sceneryForward(g.userData.anchor,d,560,60);g.position.set(g.userData.x+bend(f,d,track),rise(f,d,track)-.3,-f);g.rotation.y=-heading(f,d,track);g.visible=s.worldId==='night'&&f<340;}
  for(const g of chevrons){const f=sceneryForward(g.userData.anchor,d,546,60);g.position.set(g.userData.x+bend(f,d,track),rise(f,d,track),-f);g.rotation.y=-heading(f,d,track);g.visible=f<325;}
 }};
}
export function createRouteEnvironment(scene,renderer,details){
 const baseEnvironment=scene.environment,loaded=new Map(),pending=new Map();let active='coast',lamps=[];
 async function ensure(id){id=validRoute(id);if(id==='coast'||loaded.has(id))return;if(pending.has(id))return pending.get(id);const work=(async()=>{const loader=new GLTFLoader(),root=new THREE.Group();root.visible=false;scene.add(root);try{let world,sky;const hdri=new RGBELoader();if(id==='city'){const [maps,kit,hdr]=await Promise.all([textures('concrete_wall_006',renderer),loader.loadAsync(path+'modular_urban_apartments_facade.glb'),hdri.loadAsync(path+'evening_road_01_puresky_1k.hdr')]);world=cityScene(root,{concrete:standard('#b1bac6',maps),kit:kit.scene});sky=hdr;}else{const [maps,cliff,boulder,hdr]=await Promise.all([textures('rock_face_03',renderer),loader.loadAsync(path+'rock_face_01.glb'),loader.loadAsync(path+'boulder_01.glb'),hdri.loadAsync(path+'kloofendal_48d_partly_cloudy_puresky_2k.hdr')]);world=mountainScene(root,{rock:maps,cliff:cliff.scene,boulder:boulder.scene,details});sky=hdr;}sky.mapping=THREE.EquirectangularReflectionMapping;const pmrem=new THREE.PMREMGenerator(renderer),env=pmrem.fromEquirectangular(sky);pmrem.dispose();loaded.set(id,{root,world,sky,environment:env.texture});}catch(e){scene.remove(root);throw e;}finally{pending.delete(id);}})();pending.set(id,work);return work;}
 return {ensure,get lamps(){return lamps;},update(s){active=validRoute(s.routeId);for(const [id,data] of loaded){data.root.visible=id===active;if(id===active){const key=s.trackProfile+'|'+s.distance+'|'+s.worldId;if(key!==data.lastKey){data.world.update(s);data.lastKey=key;}lamps=data.world.lamps;}}if(active==='coast')lamps=[];},atmosphere(s){const data=loaded.get(active);if(!data){scene.environment=baseEnvironment;scene.backgroundIntensity=1;scene.environmentRotation.y=0;return;}scene.background=data.sky;scene.environment=data.environment;const night=s.worldId==='night',wet=s.worldId==='rain';scene.backgroundIntensity=night?.04:wet?.22:active==='city'?.15:.75;scene.environmentIntensity=night?.22:wet?.5:active==='city'?.7:.9;scene.backgroundRotation.y=active==='city'?.8:1.6;scene.environmentRotation.y=scene.backgroundRotation.y;},section(s){return routeSection(validRoute(s.routeId),s.distance);}};
}
